insert into azura_import.project_fact (field, value, confidence, sources, conflicts, note) values ('hotel.brandAffiliation', 'null'::jsonb, 'conflicted', '[{"url": "https://www.turizmguncel.com/haber/ahmet-cebeci-wyndham-markasini-alanyaya-getiriyor", "publisher": "Turizm Güncel", "fetchedAt": "2026-07-27T14:48:56.060Z", "snapshotHash": "e5aaffeab5baaf63be7643eb01cdb0f1f948103c89b1e199f1a8745ccc1e2343", "tier": 6}]'::jsonb, '[{"value": "Wyndham Hotels & Resorts", "source": {"url": "https://www.turizmguncel.com/haber/ahmet-cebeci-wyndham-markasini-alanyaya-getiriyor", "publisher": "Turizm Güncel", "fetchedAt": "2026-07-27T14:48:56.060Z", "snapshotHash": "e5aaffeab5baaf63be7643eb01cdb0f1f948103c89b1e199f1a8745ccc1e2343", "tier": 6}}]'::jsonb, 'No CURRENT chain affiliation is asserted. The only source naming a chain is a 2023 press report of a Wyndham licence agreement, retained above. Against it: the hotel''s own site (tier 3, harvested 2026-07-27) names no chain anywhere in its copy, and Agoda and OnTheBeach both list the property as ''ex. Wyndham Alanya''. A licence signed in 2023 is not evidence of a brand in 2026 — see F-007 and F-018.');
insert into azura_import.finding (id, severity, area, field, message, resolution, resolved_to, competing) values ('F-001', 'high', 'structure', 'project.residenceBlockCount', 'CORRECTED BY THE W0-B HARVEST. SOURCES.md §3 recorded a three-way split — 3 (Housearch) vs 7 residence blocks (Seaside, ENS Pride) vs 14 buildings of 6 floors (Haspo) — and treated Housearch''s 3 as an uncorroborated outlier. Reading Housearch''s markup shows it states NO block count for this project at all: the 3 sits inside its developer panel and counts Cebeci Group''s whole portfolio on Housearch, matching that site''s own ''Property from Cebeci Group — 3 new buildings'' link. So the outlier was never a disagreement about Azura World; it was a figure about a different subject read out of context on the shallow pass. What remains is two compatible facts: 7 residence blocks CONTAINING 14 buildings of 6 floors.', 'residenceBlockCount = 7, now confirmed across three independent hosts (Seaside, ENS Pride, Capital Estate). buildingCount = 14 stays single_source on Haspo. No value is suppressed — there is simply no competing block count left once Housearch''s portfolio counter is read as what it is. This is the clearest case in the build for why the deep harvest exists: the shallow pass produced a plausible conflict out of a correctly-quoted number.', '7'::jsonb, '[{"value": 7, "source": {"url": "https://www.cestate.net/building/AzuraWorld", "publisher": "Capital Estate", "fetchedAt": "2026-07-27T14:48:50.999Z", "snapshotHash": "461832b1eb58703503de109d9cfd65e842637f83686b3a035fc135b96b2a64dd", "tier": 6}}, {"value": 7, "source": {"url": "https://enspride.com/property/azura-world-residence-hotel-a-new-iconic-lifestyle-concept-in-alanya/", "publisher": "ENS Pride", "fetchedAt": "2026-07-27T14:48:12.142Z", "snapshotHash": "36e5a6844ac2ff181c400a3898b677f7985474167a43ac82c2885c2cff4fce0c", "tier": 6}}, {"value": 7, "source": {"url": "https://www.seaside-alanya.com/de/antalya-alanya/residence/azura-world-residence", "publisher": "Seaside Alanya", "fetchedAt": "2026-07-27T14:47:31.915Z", "snapshotHash": "3d74064c8eb4e79bb1bcfbf5c5647aa8b1b49818f41820c6bf14ac3fff03a7f6", "tier": 4}}, {"value": 7, "source": {"url": "https://www.seaside-alanya.com/en/property/-azura-world-residence-hotel-apartments-for-sale-new-project", "publisher": "Seaside Alanya", "fetchedAt": "2026-07-27T14:47:36.436Z", "snapshotHash": "dc63100403cd03693b16636b9cf2531d08e91f7a26c0514f9095cb7ed71358c1", "tier": 4}}, {"value": 14, "source": {"url": "https://hasporealty.com/de/complex/azura-world/", "publisher": "Haspo Realty", "fetchedAt": "2026-07-27T14:47:23.370Z", "snapshotHash": "23bb2b7bc3451f75ca0191786c58ae0805781e41d3dcfb44b2ae13b4a940f694", "tier": 4}}, {"value": 14, "source": {"url": "https://hasporealty.com/en/complex/azura-world/", "publisher": "Haspo Realty", "fetchedAt": "2026-07-27T14:47:28.741Z", "snapshotHash": "4ab2f7b51da8d0d2e037b84259ccfe1f1e43e23589cd3f3137873cf720618e78", "tier": 4}}]'::jsonb);
insert into azura_import.finding (id, severity, area, field, message, resolution, resolved_to, competing) values ('F-002', 'critical', 'pricing', 'units[].askingPrice', 'The 1+1 entry price is unresolved across 19 observations from 6 publishers (Alanya-Home, Capital Estate, Haspo Realty, Housearch, Seaside Alanya, TERRA Real Estate). In EUR, the 13 observations whose publisher states a 1+1 layout run 112,000 to 310,000 EUR (Capital Estate, Haspo Realty, Seaside Alanya). That is a factor of 2.8 within EUR alone. In USD, the 2 observations whose publisher states a 1+1 layout run 238,967 to 239,171 USD (Housearch). Those differ by 0.1% within USD. The currencies are NOT converted and NOT compared to each other: no source in this dataset publishes an exchange rate or a rate date, so any ratio spanning them would be arithmetic on an invented rate. A further 4 rows are portal ''price from'' entries whose publisher did not attach a layout, so they are carried but excluded from the ratio above: 125,000 EUR (Alanya-Home), 200,000 EUR (TERRA Real Estate), 220,000 EUR (Alanya-Home), 400,000 EUR (TERRA Real Estate). The causes compound: two currencies, no observation dates, different unit subsets, and 8 of 19 observations come from listings flagged stale (F-006).', 'DELIBERATELY UNRESOLVED. Rendered as a range with all sources visible and a ''prices disagree across portals'' badge. No average, no midpoint, no ''most likely'' pick — any single number here would be a fabrication with a citation stapled to it. This is the project''s primary honesty gate.', 'null'::jsonb, '[{"value": {"amount": 112000.0, "currency": "EUR", "layout": "1+1", "interiorM2": 80.0, "isStale": true, "isEntryPrice": false, "note": null}, "source": {"url": "https://hasporealty.com/de/complex/azura-world/", "publisher": "Haspo Realty", "fetchedAt": "2026-07-27T14:47:23.370Z", "snapshotHash": "23bb2b7bc3451f75ca0191786c58ae0805781e41d3dcfb44b2ae13b4a940f694", "tier": 4}}, {"value": {"amount": 125000.0, "curre