insert into azura_import.finding (id, severity, area, field, message, resolution, resolved_to, competing) values ('F-006', 'high', 'availability', 'project.buildStatus', 'Build status: ''completed'' (Housearch) vs ''under construction'' (Haspo). Completion 2024-05-30 is corroborated by three hosts and this harvest ran 2026-07-27, so Haspo''s listing is stale by roughly two years.', 'buildStatus = completed. Consequence, and this is the part that matters: every price harvested from Haspo inherits isStale = true and must be flagged wherever shown, because a stale price presented as current is the most damaging error this project can make.', '"completed"'::jsonb, '[{"value": "completed", "source": {"url": "https://www.cebecigroup.com/en/projects", "publisher": "Cebeci Group", "fetchedAt": "2026-07-27T14:47:18.081Z", "snapshotHash": "21b88be518266cdd79724b0424a30982000445ea4d694a38cc5f9a28fc61c08f", "tier": 2}}, {"value": "under_construction", "source": {"url": "https://www.cestate.net/building/AzuraWorld", "publisher": "Capital Estate", "fetchedAt": "2026-07-27T14:48:50.999Z", "snapshotHash": "461832b1eb58703503de109d9cfd65e842637f83686b3a035fc135b96b2a64dd", "tier": 6}}, {"value": "under_construction", "source": {"url": "https://hasporealty.com/de/complex/azura-world/", "publisher": "Haspo Realty", "fetchedAt": "2026-07-27T14:47:23.370Z", "snapshotHash": "23bb2b7bc3451f75ca0191786c58ae0805781e41d3dcfb44b2ae13b4a940f694", "tier": 4}}, {"value": "under_construction", "source": {"url": "https://hasporealty.com/en/complex/azura-world/", "publisher": "Haspo Realty", "fetchedAt": "2026-07-27T14:47:28.741Z", "snapshotHash": "4ab2f7b51da8d0d2e037b84259ccfe1f1e43e23589cd3f3137873cf720618e78", "tier": 4}}, {"value": "completed", "source": {"url": "https://housearch.com/de/turkey/residential-complexes/azura-world-3403639/", "publisher": "Housearch", "fetchedAt": "2026-07-27T14:47:21.849Z", "snapshotHash": "643c8293224695449ccbdd26f25bb41fb8d4fe7154f61e37cabcbd765e01bb1e", "tier"